async function api(path,opt){const r=await fetch(root+path,{headers:{'content-type':'application/json','accept':'application/json','X-CSRF-Token':csrfToken()},credentials:'same-origin',...opt});const raw=await r.text();let j={};try{j=raw?JSON.parse(raw):{}}catch{throw Error('Yönetim API geçersiz yanıt verdi: HTTP '+r.status)}if(!r.ok)throw Error((j.error||('Yönetim API hatası: HTTP '+r.status))+(Array.isArray(j.errors)?' '+j.errors.map(x=>'Satır '+x.row+': '+x.error).join(' • '):''));return j}
